def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    pressure_bids = []
    low_budget_count = 0
    urgent_opp_count = 0

    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) <= DAILY_SALARY * 1.2:
                low_budget_count += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp_count += 1
            prev = opp.get('previous_trace', {})
            if prev:
                bid = prev.get('bid')
                if bid is not None:
                    prev_bids.append(bid)
                    weight = 1.0
                    if opp.get('water_requirement', WATER_REQ) <= supply:
                        weight += 0.1
                    if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                        weight += 0.15
                    pressure_bids.append(bid * weight)

    if budget <= 0:
        return 0.0

    slots = max(1, int(supply // WATER_REQ))
    competitors = 1 + len(alive_opponents)
    tightness = competitors - slots
    very_tight = tightness >= 2
    tight = tightness >= 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    effective_pressure = max(pressure_bids) if pressure_bids else 0.0

    if not alive_opponents:
        if hp <= 3 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.22))

    survival_urgent = hp <= 3 or no_water_days >= 1
    caution = hp <= 5

    if survival_urgent:
        target = max(DAILY_SALARY * 0.92, highest_prev + 3.0, effective_pressure)
        if very_tight:
            target = max(target, DAILY_SALARY * 1.02)
        return float(min(budget, target))

    if very_tight:
        if effective_pressure >= DAILY_SALARY * 1.6:
            target = DAILY_SALARY * 0.34
        elif effective_pressure >= DAILY_SALARY * 1.0:
            target = max(DAILY_SALARY * 0.58, highest_prev + 2.0)
        else:
            target = DAILY_SALARY * 0.52
        if caution:
            target = max(target, DAILY_SALARY * 0.72)
        return float(min(budget, target))

    if tight:
        target = DAILY_SALARY * 0.44
        if highest_prev > 0:
            if highest_prev <= DAILY_SALARY * 0.75:
                target = max(target, highest_prev + 1.5)
            elif highest_prev <= DAILY_SALARY * 1.05:
                target = max(target, DAILY_SALARY * 0.62)
            else:
                target = DAILY_SALARY * 0.36
        if urgent_opp_count >= 2:
            target += 4.0
        if low_budget_count >= 2:
            target -= 3.0
        if caution:
            target = max(target, DAILY_SALARY * 0.68)
        return float(min(budget, max(0.0, target)))

    target = DAILY_SALARY * 0.24
    if highest_prev > 0 and highest_prev < DAILY_SALARY * 0.6:
        target = max(target, highest_prev * 0.75)
    if caution:
        target = max(target, DAILY_SALARY * 0.42)
    if day >= 8 and hp >= 6:
        target *= 0.85
    return float(min(budget, max(0.0, target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    max_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Base bid: aim to be competitive but not reckless
    # If supply is tighter (closer to 15), bid a bit higher.
    supply_factor = (25.0 - supply) / 10.0  # 0 at 25, 1 at 15
    supply_factor = max(0.0, min(1.0, supply_factor))

    # If yesterday's max bid was very high, others likely bid aggressively for survival.
    pressure = 0.0
    if max_prev_bid >= DAILY_SALARY * 1.7:
        pressure = 1.0
    elif max_prev_bid >= DAILY_SALARY * 1.2:
        pressure = 0.6
    elif max_prev_bid >= DAILY_SALARY * 0.8:
        pressure = 0.3

    # HP-based urgency
    if hp <= 1:
        hp_urgency = 1.0
    elif hp <= 3:
        hp_urgency = 0.8
    elif hp <= 5:
        hp_urgency = 0.5
    else:
        hp_urgency = 0.25

    # Construct target bid
    target = DAILY_SALARY * (0.45 + 0.25 * supply_factor + 0.25 * pressure + 0.25 * hp_urgency)

    # If we are extremely low on budget, scale down
    if budget < DAILY_SALARY * 0.6:
        target = min(target, budget * 0.9)

    # Ensure we don't overshoot budget
    bid = max(0.0, min(budget, target))

    # Small deterministic tie-breaker: alternate slightly by day parity
    if int(day) % 2 == 0:
        bid = bid * 1.02
    else:
        bid = bid * 0.98

    bid = max(0.0, min(budget, bid))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, max(1, DAILY_SALARY * 0.4))

    # Collect yesterday's bids from alive opponents' traces
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine base bid considering my health and days left
    days_left = 10 - day
    urgency = (WATER_REQ - no_water_days) / WATER_REQ  # urgency scale 0-1
    if hp <= 2 or no_water_days >= 3:
        base = DAILY_SALARY * 0.9
    elif hp <= 4:
        base = DAILY_SALARY * 0.75
    else:
        base = DAILY_SALARY * 0.6

    # Adjust based on supply (if supply plentiful, bid lower)
    if supply > 20:
        base *= 0.85
    elif supply < 17:
        base *= 1.15

    # React to yesterday's bids: try to outbid the highest if needed, but cap
    if yesterday_bids:
        highest_prev = max(yesterday_bids)
        if highest_prev > DAILY_SALARY * 0.8 and budget > highest_prev + 1:
            # Compete only if we have enough budget and low urgency
            if urgency < 0.3:
                target = highest_prev - 5  # try to undercut
            else:
                target = highest_prev + 1
        else:
            target = max(base, highest_prev * 0.9)
    else:
        target = base

    # Ensure we don't exceed budget or go below 1
    bid = max(1, min(budget, target))
    return bid
